#!/usr/bin/env python3

"""Calculate pairwise SNP statistics from an AFA distance matrix."""

import argparse
import itertools
from pathlib import Path

import pandas as pd


def parse_arguments():
    """Parse command-line arguments."""
    parser = argparse.ArgumentParser(
        description=(
            "Calculate global and per-reference statistics from a "
            "pairwise SNP distance matrix generated by afa-pairwise.pl."
        )
    )

    parser.add_argument(
        "-i",
        "--input",
        required=True,
        help="Input TSV file containing the pairwise SNP distance matrix.",
    )

    parser.add_argument(
        "-a",
        "--alignment",
        required=False,
        default=None,
        help=(
            "Optional Snippy-core core.clean.aln FASTA file. "
            "If provided, compared_positions and snp_distance "
            "are calculated for each pair."
        ),
    )

    parser.add_argument(
        "-r",
        "--reference",
        required=True,
        help=(
            "Path to the reference FASTA file used by Snippy."
        ),
    )

    parser.add_argument(
        "-o",
        "--output",
        required=True,
        help="Output TSV file containing the analysis results.",
    )

    return parser.parse_args()


def read_distance_matrix(input_file):
    """Read and validate the pairwise distance matrix."""

    # Read sample IDs as strings to preserve values such as "001".
    matrix = pd.read_csv(
        input_file,
        sep="\t",
        index_col=0,
        dtype=str,
    )

    if matrix.empty:
        raise ValueError("The input distance matrix is empty.")

    # Convert distance values to numeric.
    matrix = matrix.apply(pd.to_numeric, errors="coerce")

    # A pairwise distance matrix must be square.
    if matrix.shape[0] != matrix.shape[1]:
        raise ValueError(
            "The input file does not contain a square distance matrix."
        )

    # Check that row and column sample IDs are identical.
    if list(matrix.index) != list(matrix.columns):
        raise ValueError(
            "Row and column sample IDs do not match."
        )

    return matrix


def read_alignment(alignment_file):
    """Read a FASTA alignment and return sequences indexed by sample ID."""

    sequences = {}

    current_id = None
    current_sequence = []

    # Parse the FASTA directly to avoid an additional dependency.
    with alignment_file.open("r", encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()

            if not line:
                continue

            if line.startswith(">"):
                # Store the previous sequence before starting a new one.
                if current_id is not None:
                    sequences[current_id] = "".join(
                        current_sequence
                    ).upper()

                # Keep the FASTA identifier as a string.
                current_id = line[1:].split()[0]
                current_sequence = []

            else:
                if current_id is None:
                    raise ValueError(
                        "Invalid FASTA file: sequence found before "
                        "the first header."
                    )

                current_sequence.append(line)

        # Store the final sequence.
        if current_id is not None:
            sequences[current_id] = "".join(
                current_sequence
            ).upper()

    if not sequences:
        raise ValueError(
            f"No sequences found in alignment: {alignment_file}"
        )

    return sequences


def get_compared_positions(sequence_1, sequence_2):
    """Count positions that can be compared between two sequences."""

    if len(sequence_1) != len(sequence_2):
        raise ValueError(
            "Sequences used for pairwise comparison have different lengths."
        )

    compared_positions = 0

    for base_1, base_2 in zip(sequence_1, sequence_2):
        # Ignore positions containing gaps or ambiguous nucleotides.
        if base_1 in {"N", "-"} or base_2 in {"N", "-"}:
            continue

        compared_positions += 1

    return compared_positions


def get_unique_pairwise_distances(matrix):
    """Extract each pairwise distance only once."""

    pairs = []

    sample_ids = list(matrix.index)

    # Generate every unique combination exactly once.
    for sample_1, sample_2 in itertools.combinations(sample_ids, 2):
        distance = matrix.loc[sample_1, sample_2]

        if pd.notna(distance):
            pairs.append(
                (
                    sample_1,
                    sample_2,
                    float(distance),
                )
            )

    if not pairs:
        raise ValueError(
            "No valid pairwise distances were found."
        )

    return pairs


def calculate_statistics(values):
    """Calculate descriptive statistics for a collection of distances."""

    values = pd.Series(values, dtype=float)

    return {
        "mean": values.mean(),
        "median": values.median(),
        "minimum": values.min(),
        "Q1": values.quantile(0.25),
        "Q3": values.quantile(0.75),
        "maximum": values.max(),
    }


def calculate_global_statistics(matrix, pairs, reference):
    """Calculate statistics across all unique sample pairs."""

    distances = [
        distance
        for _, _, distance in pairs
    ]

    statistics = {
        "number_of_samples": len(matrix),
        "number_of_unique_pairs": len(pairs),
        "reference": str(Path(reference).name),
    }

    statistics.update(
        calculate_statistics(distances)
    )

    return statistics


def calculate_reference_statistics(matrix):
    """Calculate statistics for each sample used as a reference."""

    reference_statistics = {}

    for sample in matrix.index:
        # Exclude the self-comparison from the reference distances.
        distances = matrix.loc[sample].drop(labels=sample)

        # Remove missing values.
        distances = distances.dropna().astype(float)

        if distances.empty:
            raise ValueError(
                f"No valid distances found for sample '{sample}'."
            )

        reference_statistics[sample] = calculate_statistics(
            distances
        )

    return reference_statistics


def calculate_pair_information(pairs, sequences):
    """Calculate pairwise information in both directions."""

    pair_information = []

    for sample_1, sample_2, snp_count in pairs:
        sequence_1 = sequences[sample_1]
        sequence_2 = sequences[sample_2]

        compared_positions = get_compared_positions(
            sequence_1,
            sequence_2,
        )

        if compared_positions > 0:
            snp_distance = (
                snp_count / compared_positions
            )
        else:
            snp_distance = None

        # Add both orientations of the pair.
        pair_information.append(
            (
                sample_1,
                sample_2,
                snp_count,
                compared_positions,
                snp_distance,
            )
        )

        pair_information.append(
            (
                sample_2,
                sample_1,
                snp_count,
                compared_positions,
                snp_distance,
            )
        )

    # Sort by sample_1 first, then by sample_2.
    pair_information.sort(
        key=lambda pair: (pair[0], pair[1])
    )

    return pair_information


def calculate_pair_information_without_alignment(pairs):
    """Create pairwise information without alignment-derived metrics."""

    pair_information = []

    for sample_1, sample_2, snp_count in pairs:
        # Add both orientations of the pair.
        pair_information.append(
            (
                sample_1,
                sample_2,
                snp_count,
                None,
                None,
            )
        )

        pair_information.append(
            (
                sample_2,
                sample_1,
                snp_count,
                None,
                None,
            )
        )

    # Sort by sample_1 first, then by sample_2.
    pair_information.sort(
        key=lambda pair: (pair[0], pair[1])
    )

    return pair_information


def format_value(value):
    """Format numerical values for the output TSV."""

    if value is None or pd.isna(value):
        return "NA"

    if isinstance(value, float):
        if value.is_integer():
            return str(int(value))

        return f"{value:.6f}"

    return str(value)


def write_statistics(output, statistics):
    """Write a statistics dictionary to the output file."""

    for name, value in statistics.items():
        output.write(
            f"{name}\t{format_value(value)}\n"
        )


def write_results(
    output_file,
    global_statistics,
    reference_statistics,
    pair_information,
):
    """Write all analysis results to a single TSV file."""

    with output_file.open("w", encoding="utf-8") as output:

        # --------------------------------------------------------------
        # General statistics - all pair
        # --------------------------------------------------------------
        output.write("# GLOBAL PAIRWISE STATISTICS\n")

        write_statistics(
            output,
            global_statistics,
        )

        output.write("\n################################################################################\n")

        # --------------------------------------------------------------
        # Statistics for each sample used as a reference
        # --------------------------------------------------------------
        output.write("# REFERENCE-BASED STATISTICS\n")

        for sample, statistics in reference_statistics.items():
            output.write(
                f"ref = {sample}\n"
            )

            write_statistics(
                output,
                statistics,
            )

            output.write("\n")

        # --------------------------------------------------------------
        # Pairwise SNP information
        # --------------------------------------------------------------
        output.write("################################################################################\n")
        output.write("# PAIRWISE SNP DETAILS\n")

        output.write("sample_1\tsample_2\tsnp_count\tcompared_positions\tsnp_distance\n")

        for (
            sample_1,
            sample_2,
            snp_count,
            compared_positions,
            snp_distance,
        ) in pair_information:
            output.write(
                f"{sample_1}\t"
                f"{sample_2}\t"
                f"{format_value(snp_count)}\t"
                f"{format_value(compared_positions)}\t"
                f"{format_value(snp_distance)}\n"
            )


def main():
    """Run the pairwise SNP statistics analysis."""

    args = parse_arguments()

    input_file = Path(args.input)
    output_file = Path(args.output)
    reference_file = Path(args.reference)

    if not input_file.is_file():
        raise FileNotFoundError(
            f"Input distance matrix not found: {input_file}"
        )

    # The reference path is stored in the output even if the file
    # itself is not available in the current execution environment.
    reference = str(reference_file)

    # Read and validate the pairwise distance matrix.
    matrix = read_distance_matrix(input_file)

    # Extract each unique pair only once.
    pairs = get_unique_pairwise_distances(matrix)

    # Calculate global statistics using unique pairs only.
    global_statistics = calculate_global_statistics(
        matrix,
        pairs,
        reference,
    )

    # Calculate statistics for every sample as a reference.
    reference_statistics = calculate_reference_statistics(
        matrix
    )

    # Calculate pairwise information.
    if args.alignment is not None:
        alignment_file = Path(args.alignment)

        if not alignment_file.is_file():
            raise FileNotFoundError(
                f"Alignment file not found: {alignment_file}"
            )

        sequences = read_alignment(alignment_file)

        # Check that all samples from the distance matrix are present.
        missing_samples = set(matrix.index) - set(sequences)

        if missing_samples:
            missing = ", ".join(
                sorted(missing_samples)
            )

            raise ValueError(
                "The following samples are missing from the alignment: "
                f"{missing}"
            )

        pair_information = calculate_pair_information(
            pairs,
            sequences,
        )

    else:
        # Without an alignment, alignment-derived metrics are unavailable.
        pair_information = calculate_pair_information_without_alignment(
            pairs
        )

    # Write the complete result file.
    write_results(
        output_file,
        global_statistics,
        reference_statistics,
        pair_information,
    )

    print(f"Input matrix: {input_file}")
    print(f"Reference: {reference}")
    print(f"Number of samples: {len(matrix)}")
    print(f"Number of unique pairs: {len(pairs)}")

    if args.alignment is not None:
        print(f"Alignment: {args.alignment}")
        print("Compared positions and SNP distances: calculated")
    else:
        print(
            "Compared positions and SNP distances: NA "
            "(no alignment provided)"
        )

    print(f"Output file: {output_file}")


if __name__ == "__main__":
    main()
